ALTER TABLE prevailing_wage 
ADD COLUMN IF NOT EXISTS wage_tier TEXT;

CREATE OR REPLACE FUNCTION update_wage_competitiveness()
RETURNS TRIGGER AS $$
DECLARE
    wage_from NUMERIC;
    prev_wage NUMERIC;
    wage_unit enum_wage_unit_of_pay;
    pw_unit enum_pw_unit_of_pay;
    offered_annual NUMERIC;
    prevailing_annual NUMERIC;
    wdr NUMERIC;
BEGIN
    wage_from := REGEXP_REPLACE(
        NEW.wage_details -> 'offered_wage' ->> 'from', '[^0-9\.]+', '', 'g'
    )::NUMERIC;

    prev_wage := REGEXP_REPLACE(
        NEW.wage_details -> 'prevailing_wage' ->> 'value', '[^0-9\.]+', '', 'g'
    )::NUMERIC;

    wage_unit := (NEW.wage_details -> 'offered_wage' ->> 'unit')::enum_wage_unit_of_pay;
    pw_unit := (NEW.wage_details -> 'prevailing_wage' ->> 'unit')::enum_pw_unit_of_pay;

    offered_annual := CASE wage_unit
        WHEN 'Hour' THEN wage_from * 2080
        WHEN 'Week' THEN wage_from * 52
        WHEN 'Year' THEN wage_from
        ELSE NULL
    END;

    prevailing_annual := CASE pw_unit
        WHEN 'Hour' THEN prev_wage * 2080
        WHEN 'Week' THEN prev_wage * 52
        WHEN 'Month' THEN prev_wage * 12
        WHEN 'Year' THEN prev_wage
        ELSE NULL
    END;

    IF prevailing_annual IS NULL OR prevailing_annual = 0 THEN
        wdr := NULL;
    ELSE
        wdr := ((offered_annual - prevailing_annual) / prevailing_annual) * 100;
    END IF;

    NEW.wage_tier := CASE
        WHEN wdr IS NULL THEN NULL
        WHEN wdr < 0 THEN 'Below-Market'
        WHEN wdr BETWEEN 0 AND 10 THEN 'Market-Competitive'
        ELSE 'Premium'
    END;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS wage_competitiveness_trigger ON prevailing_wage;

CREATE TRIGGER wage_competitiveness_trigger
BEFORE INSERT OR UPDATE ON prevailing_wage
FOR EACH ROW
EXECUTE FUNCTION update_wage_competitiveness();
